-- Datos demo alineados con el formato institucional GFR-FOR-005:
-- 1) Los syllabus demo usan los rótulos de corte de la plantilla (I, II, III; ver V4).
-- 2) Ingeniería de Software toma el contenido real del syllabus institucional 103093 para comparar
--    el PDF exportado con el documento oficial. Usa las convenciones del editor: «- » viñeta ✔,
--    «  - » subviñeta o, **negrita**, *cursiva* y subtítulos en mayúsculas.
UPDATE syllabus_sections
SET evaluation = replace(replace(replace(evaluation::text,
        '"label": "PRIMER CORTE"', '"label": "I"'),
        '"label": "SEGUNDO CORTE"', '"label": "II"'),
        '"label": "TERCER CORTE"', '"label": "III"')::jsonb
WHERE evaluation IS NOT NULL;

UPDATE syllabus_sections SET content = t.content
FROM (VALUES
    ('justification', E'Los ingenieros de sistemas están constantemente relacionados con actividades que tienen que ver con el desarrollo de software. Estas actividades deben llevarse a cabo según algún proceso establecido, aplicando técnicas y métodos propios de la profesión, y cumpliendo con las expectativas de los usuarios.\n\nEste curso presenta las técnicas y métodos que permiten afrontar con el profesionalismo requerido las actividades de estimación, diseño y evolución del código en los proyectos de desarrollo de software, junto con las prácticas de trabajo colaborativo y de calidad que sostienen a un equipo a lo largo del ciclo de vida del producto.'),
    ('performance', E'RESULTADOS DE APRENDIZAJE:\n\n**SO2** – Capacidad de aplicar el diseño de ingeniería para producir soluciones que satisfagan necesidades específicas teniendo en cuenta la salud pública, la seguridad y el bienestar, así como factores globales, culturales, sociales, ambientales y económicos.\n\nINDICADOR DE DESEMPEÑO:\n\n**PI1:** Identifica necesidades, requerimientos y criterios específicos para abordar diferentes problemas de ingeniería considerando la salud, seguridad y bienestar público, así como factores globales, culturales, sociales, ambientales y económicos.\n\n**PI2:** Diseñar un sistema informático que satisfaga los requisitos correspondientes a las necesidades identificadas en el contexto en que surge.'),
    ('contents', E'**Gestión y proceso de desarrollo**\n- Metodología Scrum\n  - Valores y pilares del marco (Transparencia, inspección, adaptación)\n  - Roles: Product Owner, Scrum Master, Equipo de Desarrollo\n  - Artefactos: Product Backlog, Sprint Backlog, Incremento\n  - Eventos: Sprint, Planning, Daily, Review, Retrospectiva\n  - Historias de usuario, criterios de aceptación y definición "Done"\n  - Métricas: burndown, velocidad, gestión visual del tablero\n- Principios SOLID\n  - Responsabilidad Única (SRP)\n  - Abierto/Cerrado (OCP)\n  - Sustitución de Liskov (LSP)\n  - Segregación de Interfaces (ISP)\n  - Inversión de Dependencias (DIP)\n  - Detección de violaciones en código existente y su corrección\n\n**Trabajo colaborativo y calidad del código**\n\n- GitFlow\n  - Repositorios distribuidos: ramas, merge, rebase y resolución de conflictos\n  - Modelo GitFlow: main, develop, feature, release, hotfix\n  - Comparación con Trunk Based Development y GitHub Flow\n  - Pull Requests, revisión de código entre pares y convenciones de commits\n  - Versionamiento semántico e integración con pipelines de CI\n\n**Diseño evolutivo del software**\n\n- Refactorización y Clean Code\n  - Deuda técnica y code smells (código duplicado, métodos largos, clases dios, envidia de atributos, obsesión por primitivos)\n  - Catálogo de refactorizaciones (extraer método/clase, renombrar, reemplazar condicional por polimorfismo)\n  - Nombres, funciones, comentarios, formato y manejo de errores\n  - Pruebas unitarias como red de seguridad de la refactorización\n  - Análisis estático de código y métricas de mantenibilidad\n- Patrones de Diseño\n  - Definición, clasificación (creacionales, estructurales, de comportamiento) y relación con los principios SOLID\n  - Creacionales: Singleton, Factory Method, Builder\n  - Estructurales: Adapter, Decorator, Composite\n  - Comportamiento: Strategy, Observer, Template Method\n  - Aplicación de patrones como resultado de una refactorización\n  - Antipatrones y sobreingeniería\n- Técnicas de estimación\n  - Estimación por juicio experto y por analogía\n  - Descomposición de trabajo (WBS) y estimación por tres puntos\n  - Estimación relativa: story points, Planning Poker, T-shirt sizing\n  - Velocidad del equipo, capacidad y proyección de entregas\n  - Errores comunes: cono de incertidumbre, sesgo de optimismo, padding\n- Pruebas de código\n  - Niveles de pruebas\n  - Pruebas unitarias\n  - Pruebas estáticas de código\n  - Análisis de cobertura\n- Manuales:\n  - Manual de instalación\n  - Manual de Usuario\n  - Manual de Administración'),
    ('teaching_strategies', E'En cada sesión del curso se discutirán los conceptos teóricos de cada tema, que los estudiantes han preparado previamente, y se desarrollarán talleres individuales o en grupos, con ejercicios de aplicación. La preparación de cada tema incluye la lectura del mismo, identificar las ideas más importantes y sobre todo establecer los puntos que necesitan explicación por parte del docente. Algunas lecturas y actividades serán en idioma inglés, considerando que gran parte de la producción en el tema es en dicho idioma.\n\nSe establecerán espacios para asesorías, donde se resolverán dudas relacionadas con los temas de la materia y se realizará seguimiento al desarrollo de los talleres y del proyecto. Se contará con un aula virtual –en la plataforma institucional UAMVirtual– donde se publicará material del curso (estándares, talleres, lecturas) y las fechas para las diferentes actividades. En el aula se contará con un foro donde se pueden plantear discusiones relacionadas con temas de la materia.\n\nAdemás del estudio individual de cada tema, los estudiantes deberán desarrollar un proyecto de software en equipo, donde se apliquen los conceptos vistos en el curso, junto con temas de investigación. El proyecto se gestionará mediante sprints y se versionará en un repositorio remoto siguiendo el modelo de ramificación estudiado, de manera que el historial del repositorio y el tablero del equipo hagan parte de la evidencia evaluable.\n\nComo elementos investigativos adicionales, los estudiantes deberán utilizar herramientas de software que apoyen el desarrollo del proyecto, y realizarán aportes sobre temas de actualidad relacionados con la Ingeniería de Software mediante herramientas Web 2.0.'),
    ('bibliography', E'Requerida\n- BENNET, Simon, McROBB, Steve y FARMER, Ray. Análisis y diseño orientado a objetos de sistemas, Tercera Edición. McGraw-Hill, 2006. [005.1 B355]\n- BRUEGGE, Bernd y DUTOIT, Allen. Ingeniería de software orientado a objetos. Prentice Hall/Pearson, 2002. [005.1 B773]\n- ERIKSSON, Hans-Erik; PENKER, Magnus; LYONS, Brian y FADO, David. UML 2 Toolkit. Wiley, 2004. [005.12 E744]\n- HUMPHREY Watts. PSP: A Self - Improvement Process for Software Engineers. Addison-Wesley, 2005. [005.1 H856p]\n- PERDITA, Stevens y POOLEY, Rob. Utilización de UML en ingeniería del software con objetos y componentes. Pearson, 2007 [005.1 S738]\n\nSugerida\n- BENNET, Simon, McROBB, Steve y FARMER, Ray. *Análisis y diseño orientado a objetos de sistemas*, Tercera Edición. McGraw-Hill, 2006. [005.1 B355]\n- BRUEGGE, Bernd y DUTOIT, Allen. *Ingeniería de software orientado a objetos*. Prentice Hall/Pearson, 2002. [005.1 B773]\n- –. *Object Oriented Software Engineering: using UML, Patterns and Java*, 3 ed. Prentice Hall, 2009. [005.1 B773o]\n- CHACON, Scott y STRAUB, Ben. *Pro Git*, 2 ed. Apress, 2014.\n- COHN, Mike. *Agile Estimating and Planning*. Prentice Hall, 2005.\n- FOWLER, Martin. *Refactoring: Improving the Design of Existing Code*, 2 ed. Addison-Wesley, 2018.\n- GAMMA, Erich et al. *Design Patterns: Elements of Reusable Object-Oriented Software*. Addison-Wesley Publishing Company, 1995. [005.12 G155]\n- MARTIN, Robert C. *Clean Code: A Handbook of Agile Software Craftsmanship*. Prentice Hall, 2008.\n- MARTIN, Robert C. *Clean Architecture: A Craftsman''s Guide to Software Structure and Design*. Prentice Hall, 2017.\n- OTERO, Carlos E. *Software Engineering Design: Theory and Practice*. CRC, 2012. [005.1 O737]\n- PIATTINI, Mario; CALVO-MANZANO, José; CERVERA, Joaquín y FERNÁNDEZ, Luis. *Análisis y diseño de aplicaciones informáticas de gestión: Una perspectiva de ingeniería del software*. Alfaomega-Rama, 2004. [004.21 P417]\n- PRESSMAN, Roger. *Ingeniería del software: Un enfoque práctico*, Séptima Edición. McGraw Hill Interamericana, 2010. [005.1 P737]')
) AS t (section_type, content)
WHERE syllabus_sections.syllabus_id = '50000000-0000-0000-0000-000000000002'
  AND syllabus_sections.section_type = t.section_type;

UPDATE syllabus SET updated_at = '2026-03-01T10:00:00Z' WHERE id = '50000000-0000-0000-0000-000000000002';

-- La actualización queda en el historial (UC22) con el mismo snapshot que genera el backend.
INSERT INTO syllabus_versions (syllabus_id, version_number, snapshot, change_description, modified_by, created_at)
SELECT s.id, 2,
       jsonb_build_object(
           'title', s.title, 'status', s.status, 'headerTitle', s.header_title,
           'documentCode', s.document_code, 'documentDate', s.document_date,
           'sections', (SELECT jsonb_agg(jsonb_build_object(
                                   'sectionType', sec.section_type, 'title', sec.title, 'content', sec.content,
                                   'evaluation', sec.evaluation, 'order', sec.section_order)
                                   ORDER BY sec.section_order)
                        FROM syllabus_sections sec WHERE sec.syllabus_id = s.id)),
       'Contenido según el syllabus institucional 103093 (formato GFR-FOR-005)',
       '40000000-0000-0000-0000-000000000001', '2026-03-01T10:00:00Z'
FROM syllabus s WHERE s.id = '50000000-0000-0000-0000-000000000002';
